problems.solutionCode:
export function validateTemplateDelimiters(source: string): boolean {
  const expectedClosers: string[] = [];
  const closerFor: Record<string, string> = { "(": ")", "[": "]", "{": "}" };
  const openers = new Set(Object.keys(closerFor));
  for (const character of source) {
    if (openers.has(character)) {
      expectedClosers.push(closerFor[character]);
    } else {
      const expected = expectedClosers.pop();
      if (expected !== character) return false;
    }
  }
  return expectedClosers.length === 0;
}

