problems.solutionCode:
export type DequeueResult<T> = { ok: true; value: T } | { ok: false };
export function createJobQueue<T>() {
  const jobs: T[] = [];
  let head = 0;
  return {
    enqueue(job: T): void { jobs.push(job); },
    dequeue(): DequeueResult<T> {
      if (head >= jobs.length) return { ok: false };
      const value = jobs[head];
      head += 1;
      if (head === jobs.length) { jobs.length = 0; head = 0; }
      return { ok: true, value };
    },
  };
}

