problems.solutionCode:
export type PopResult<T> = { ok: true; value: T } | { ok: false };
export function createRetryStack<T>() {
  const values: T[] = [];
  return {
    push(value: T): void { values.push(value); },
    pop(): PopResult<T> {
      if (values.length === 0) return { ok: false };
      return { ok: true, value: values.pop() as T };
    },
  };
}

